#include <stdio.h>
static int clamp(int x) { return x < 0 ? 0 : x > 100 ? 100 : x; }
int main(void) {
    int x;
    if (scanf("%d", &x)!=1) return 1;
    printf("%d\n", clamp(x));
    return 0;
}
